import heapq


def _round(value, mode):
    q, r = divmod(value, 10000)
    if mode == "half_up" and 2 * r >= 10000:
        q += 1
    return q


def _ledger(data, sequence_first, discounted_tax):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (seq, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data.get("rounding", "floor")
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted_tax else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    rows_by_version = {}
    for name in names:
        rows = {row["version"]: row for row in packages[name]}
        rows_by_version[name] = rows
        versions = sorted(v for v in rows
                          if v not in blocked.get(name, [])
                          and (name not in pins or v == pins[name]))
        domains.append([-1] + versions)

    for values in product(*domains):
        chosen = dict(zip(names, values))
        installed = {name for name, version in chosen.items() if version != -1}
        state = {}
        valid = True

        def visit(name, low, high):
            nonlocal valid
            version = chosen[name]
            if version == -1 or not low <= version <= high:
                valid = False
                return
            if state.get(name) == 1:
                valid = False
                return
            if state.get(name) == 2:
                return
            state[name] = 1
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                visit(dep["name"], dep["min"], dep["max"])
                if not valid:
                    return
            state[name] = 2

        for name, bounds in data["roots"].items():
            visit(name, bounds[0], bounds[1])
            if not valid:
                break
        if valid and set(state) == installed:
            return {"versions": {name: chosen[name] for name in names
                                 if name in installed}}
    return {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for selected in combinations(options, k):
        ids = [job["id"] for job in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(a["end"] > b["start"] for a, b in zip(ordered, ordered[1:])):
            continue
        value = sum(job["value"] for job in selected)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, 0)
    best = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    coupons = data["coupons"]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if used + spend > coupons:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_mask = mask | bits.get(nxt, 0)
                new_used = used + spend
                next_state = (nxt, new_mask, new_used)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, new_mask, new_used))
    return {"arrival": None}


